import { initializeApp, getApps, getApp, FirebaseApp } from 'firebase/app';
import { getAuth, Auth } from 'firebase/auth';
import { 
  getFirestore, 
  Firestore, 
  doc, 
  getDocFromServer, 
  collection, 
  setDoc, 
  getDoc, 
  getDocs, 
  query, 
  where, 
  onSnapshot, 
  Unsubscribe, 
  DocumentData,
  writeBatch
} from 'firebase/firestore';
import { Agency, FieldNote } from '../types';

// Load configuration generated by Firebase Provisioning
import firebaseConfig from '../../firebase-applet-config.json';

/**
 * Initialize or retrieve the active Firebase App instance
 */
export const app: FirebaseApp = getApps().length === 0 
  ? initializeApp({
      apiKey: firebaseConfig.apiKey,
      authDomain: firebaseConfig.authDomain,
      projectId: firebaseConfig.projectId,
      storageBucket: firebaseConfig.storageBucket,
      messagingSenderId: firebaseConfig.messagingSenderId,
      appId: firebaseConfig.appId
    })
  : getApp();

/**
 * Initialize Firebase Authentication
 */
export const auth: Auth = getAuth(app);

/**
 * Initialize Firestore targeting the provisioned custom database:
 * ai-studio-nicksemsfireterr-26354b36-e812-4fee-8cf9-2df9f9c26acf
 * Following the required skill pattern: getFirestore(app, firebaseConfig.firestoreDatabaseId)
 */
const targetDatabaseId = firebaseConfig.firestoreDatabaseId && firebaseConfig.firestoreDatabaseId !== '(default)'
  ? firebaseConfig.firestoreDatabaseId
  : 'ai-studio-nicksemsfireterr-26354b36-e812-4fee-8cf9-2df9f9c26acf';

export const db: Firestore = getFirestore(app, targetDatabaseId);

export const isFirestoreConfigured = Boolean(firebaseConfig.projectId && firebaseConfig.apiKey);

/**
 * Standardized Firestore Error Logging conforming to Firebase integration skill specification
 */
export enum OperationType {
  CREATE = 'create',
  UPDATE = 'update',
  DELETE = 'delete',
  LIST = 'list',
  GET = 'get',
  WRITE = 'write',
}

export interface FirestoreErrorInfo {
  error: string;
  operationType: OperationType;
  path: string | null;
  authInfo: {
    userId?: string | null;
    email?: string | null;
    emailVerified?: boolean | null;
    isAnonymous?: boolean | null;
    tenantId?: string | null;
    providerInfo?: {
      providerId?: string | null;
      email?: string | null;
    }[];
  };
}

export function handleFirestoreError(error: unknown, operationType: OperationType, path: string | null) {
  const errInfo: FirestoreErrorInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth?.currentUser?.uid || null,
      email: auth?.currentUser?.email || null,
      emailVerified: auth?.currentUser?.emailVerified || null,
      isAnonymous: auth?.currentUser?.isAnonymous || null,
      tenantId: auth?.currentUser?.tenantId || null,
      providerInfo: auth?.currentUser?.providerData?.map(provider => ({
        providerId: provider.providerId,
        email: provider.email,
      })) || []
    },
    operationType,
    path
  };
  console.warn('Firestore Error Context: ', JSON.stringify(errInfo));
  return errInfo;
}

/**
 * Test connectivity with the Firestore database using getDocFromServer
 * as mandated by Firebase integration guidelines, with a fast timeout guard
 * to prevent 10s backend unreachable stalls.
 */
export async function testFirestoreConnection(): Promise<boolean> {
  try {
    const timeoutPromise = new Promise<never>((_, reject) => 
      setTimeout(() => reject(new Error('connection timeout: operating in offline-cached mode')), 3500)
    );
    await Promise.race([
      getDocFromServer(doc(db, 'test', 'connection')),
      timeoutPromise
    ]);
    return true;
  } catch (error) {
    if (error instanceof Error && (error.message.includes('the client is offline') || error.message.includes('offline') || error.message.includes('timeout') || error.message.includes('Could not reach Cloud Firestore'))) {
      console.warn('Firestore is operating in offline-cached mode.');
      return false;
    }
    // Document not found is expected and verifies connection reached the backend
    return true;
  }
}

/**
 * Collection references for strongly-typed operations
 */
export const collections = {
  agencies: collection(db, 'agencies'),
  counties: collection(db, 'counties'),
  fieldNotes: collection(db, 'field_notes'),
  userPreferences: collection(db, 'user_preferences')
};

/**
 * Cloud persistence methods for EMS and Fire agencies across all 3,143 counties
 */

/**
 * Recursively strips any `undefined` properties from objects/arrays before passing to Firestore
 * `setDoc` or `batch.set`, preventing FirebaseError: Unsupported field value: undefined.
 */
function stripUndefinedDeep<T>(obj: T): T {
  if (obj === null || obj === undefined || typeof obj !== 'object') {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj
      .filter((item) => item !== undefined)
      .map((item) => stripUndefinedDeep(item)) as unknown as T;
  }
  const cleaned: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
    if (value !== undefined) {
      cleaned[key] = stripUndefinedDeep(value);
    }
  }
  return cleaned as T;
}

/**
 * Save or update a single agency record in Firestore
 */
export async function saveAgencyToFirestore(agency: Agency): Promise<void> {
  if (!agency || !agency.id) return;
  try {
    const agencyRef = doc(db, 'agencies', agency.id);
    const payload = stripUndefinedDeep({
      ...agency,
      _updatedAt: new Date().toISOString()
    });
    await setDoc(agencyRef, payload, { merge: true });
  } catch (err) {
    console.error('Failed to sync agency to Firestore:', agency.id, err);
    throw err;
  }
}

/**
 * Batch write initial agencies to Firestore for cloud hydration
 */
export async function batchSyncAgenciesToFirestore(agenciesList: Agency[], maxBatch: number = 25): Promise<number> {
  if (!agenciesList || agenciesList.length === 0) return 0;
  let count = 0;
  
  const targetSlice = agenciesList.slice(0, maxBatch);
  const batch = writeBatch(db);
  const nowIso = new Date().toISOString();

  for (const agency of targetSlice) {
    if (!agency.id) continue;
    const ref = doc(db, 'agencies', agency.id);
    const payload = stripUndefinedDeep({
      ...agency,
      _syncedAt: agency._syncedAt || nowIso
    });
    batch.set(ref, payload, { merge: true });
    count++;
  }

  await batch.commit();
  return count;
}

/**
 * Fetch agencies from Firestore filtered by state and/or county
 */
export async function fetchAgenciesFromFirestore(stateCode?: string, county?: string): Promise<Agency[]> {
  try {
    let q = query(collections.agencies);

    if (stateCode && stateCode !== 'all') {
      q = query(collections.agencies, where('stateCode', '==', stateCode.toUpperCase()));
    }
    if (county && county !== 'all') {
      q = query(collections.agencies, where('county', '==', county));
    }

    const snapshot = await getDocs(q);
    const results: Agency[] = [];
    snapshot.forEach(docSnap => {
      const data = docSnap.data() as Agency;
      results.push(data);
    });
    return results;
  } catch (err) {
    console.warn('Could not fetch agencies from Firestore, using local fallback:', err);
    return [];
  }
}

/**
 * Real-time subscription to agencies collection with optional state filter
 */
export function subscribeToFirestoreAgencies(
  onAgenciesUpdate: (agencies: Agency[]) => void,
  stateCode?: string
): Unsubscribe {
  let q = query(collections.agencies);
  if (stateCode && stateCode !== 'all') {
    q = query(collections.agencies, where('stateCode', '==', stateCode.toUpperCase()));
  }

  return onSnapshot(q, (snapshot) => {
    const list: Agency[] = [];
    snapshot.forEach((d) => {
      list.push(d.data() as Agency);
    });
    onAgenciesUpdate(list);
  }, (error) => {
    handleFirestoreError(error, OperationType.GET, 'agencies');
  });
}

/**
 * Save field visit notes to Firestore
 */
export async function saveFieldNoteToFirestore(agencyId: string, note: FieldNote): Promise<void> {
  const noteId = `note-${agencyId}-${Date.now()}`;
  const noteRef = doc(db, 'field_notes', noteId);
  await setDoc(noteRef, {
    ...note,
    id: noteId,
    agencyId,
    createdAt: new Date().toISOString()
  });
}
